[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #016b75;
      --teal-light: #e6f5f6;
      --teal-mid: #b3dde0;
      --charcoal: #231F20;
      --gray-900: #1a1a1a;
      --gray-700: #374151;
      --gray-600: #4B5563;
      --gray-500: #6B7280;
      --gray-400: #9CA3AF;
      --gray-200: #E5E7EB;
      --gray-100: #F3F4F6;
      --gray-50: #F9FAFB;
      --coral: #E8604C;
      --amber: #F59E0B;
      --white: #FFFFFF;
      --font: 'Inter', system-ui, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--charcoal);
      background: var(--white);
      font-size: 16px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }

    /* ===== UTILITY ===== */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

    /* ===== HEADER ===== */
    .site-header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 100;
      box-shadow: 0 1px 8px rgba(0,0,0,0.06);
    }

    .header-inner {
      display: flex;
      align-items: center;
      gap: 32px;
      height: 64px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--teal);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { fill: white; }

    .logo-text {
      font-size: 20px;
      font-weight: 800;
      color: var(--teal);
      letter-spacing: -0.5px;
    }

    .main-nav {
      display: flex;
      align-items: center;
      gap: 0;
      flex: 1;
    }

    .nav-item {
      position: relative;
    }

    .nav-trigger {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 0 14px;
      height: 64px;
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
      transition: color 0.15s;
      white-space: nowrap;
    }

    .nav-trigger:hover { color: var(--teal); }
    .nav-trigger svg { transition: transform 0.2s; }
    .nav-item.open .nav-trigger { color: var(--teal); }
    .nav-item.open .nav-trigger svg { transform: rotate(180deg); }

    .mega-menu {
      position: absolute;
      top: 100%;
      left: 0;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      box-shadow: 0 12px 40px rgba(0,0,0,0.12);
      padding: 24px;
      min-width: 520px;
      display: none;
      z-index: 200;
    }

    .nav-item.open .mega-menu { display: block; animation: menuFade 0.15s ease; }

    @keyframes menuFade {
      from { opacity: 0; transform: translateY(-6px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .mega-menu-title {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--gray-400);
      margin-bottom: 12px;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px 16px;
    }

    .mega-menu-grid.cols-2 { grid-template-columns: repeat(2, 1fr); }

    .mega-link {
      font-size: 13.5px;
      color: var(--gray-700);
      padding: 5px 0;
      display: block;
      transition: color 0.12s;
    }

    .mega-link:hover { color: var(--teal); }

    .mega-divider { border: none; border-top: 1px solid var(--gray-200); margin: 16px 0; }

    .mega-section { margin-bottom: 16px; }
    .mega-section:last-child { margin-bottom: 0; }

    .mega-section-row { display: flex; gap: 24px; }
    .mega-section-col { flex: 1; }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .btn-outline {
      padding: 7px 16px;
      border: 1.5px solid var(--teal);
      border-radius: 20px;
      font-size: 13.5px;
      font-weight: 600;
      color: var(--teal);
      transition: all 0.15s;
    }

    .btn-outline:hover { background: var(--teal); color: var(--white); }

    .btn-primary {
      padding: 7px 18px;
      background: var(--teal);
      border-radius: 20px;
      font-size: 13.5px;
      font-weight: 600;
      color: var(--white);
      transition: background 0.15s;
    }

    .btn-primary:hover { background: var(--teal-dark); }

    /* ===== TICKER ===== */
    .ticker-bar {
      background: var(--teal);
      color: var(--white);
      overflow: hidden;
      height: 40px;
      display: flex;
      align-items: center;
    }

    .ticker-track {
      display: flex;
      animation: ticker 28s linear infinite;
      white-space: nowrap;
    }

    .ticker-track:hover { animation-play-state: paused; }

    @keyframes ticker {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    .ticker-item {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 0 40px;
      font-size: 13px;
      font-weight: 500;
    }

    .ticker-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: rgba(255,255,255,0.5);
      flex-shrink: 0;
    }

    .ticker-stat { font-weight: 700; }

    /* ===== HERO ===== */
    .hero {
      background: linear-gradient(135deg, #0d4a50 0%, #02838D 50%, #049da8 100%);
      padding: 56px 0;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 48px;
      align-items: center;
      position: relative;
    }

    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.15);
      color: white;
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      padding: 5px 12px;
      border-radius: 20px;
      margin-bottom: 16px;
    }

    .hero-title {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.15;
      letter-spacing: -0.5px;
      margin-bottom: 16px;
    }

    .hero-subtitle {
      font-size: 17px;
      color: rgba(255,255,255,0.85);
      line-height: 1.6;
      margin-bottom: 28px;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--white);
      color: var(--teal);
      font-size: 15px;
      font-weight: 700;
      padding: 12px 28px;
      border-radius: 28px;
      transition: transform 0.15s, box-shadow 0.15s;
    }

    .hero-cta:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.15); }

    .hero-visual {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .hero-badge {
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 16px;
      padding: 24px;
      text-align: center;
      backdrop-filter: blur(8px);
    }

    .hero-badge-icon {
      width: 64px;
      height: 64px;
      background: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 12px;
      font-size: 28px;
    }

    .hero-badge-label {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: rgba(255,255,255,0.7);
      margin-bottom: 4px;
    }

    .hero-badge-value {
      font-size: 22px;
      font-weight: 800;
      color: var(--white);
    }

    .hero-trending {
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 12px;
      padding: 16px;
    }

    .hero-trending-title {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: rgba(255,255,255,0.6);
      margin-bottom: 10px;
    }

    .hero-trending-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 6px 0;
      border-bottom: 1px solid rgba(255,255,255,0.08);
    }

    .hero-trending-item:last-child { border-bottom: none; }

    .hero-trending-num {
      font-size: 18px;
      font-weight: 800;
      color: rgba(255,255,255,0.3);
      width: 24px;
      flex-shrink: 0;
    }

    .hero-trending-text {
      font-size: 12.5px;
      font-weight: 500;
      color: rgba(255,255,255,0.9);
      line-height: 1.4;
    }

    /* ===== TRENDING ===== */
    .trending-section {
      padding: 48px 0;
      background: var(--gray-50);
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 28px;
    }

    .section-title {
      font-size: 22px;
      font-weight: 800;
      color: var(--charcoal);
      letter-spacing: -0.3px;
    }

    .section-title span {
      color: var(--teal);
    }

    .view-all {
      font-size: 13.5px;
      font-weight: 600;
      color: var(--teal);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: gap 0.15s;
    }

    .view-all:hover { gap: 8px; }

    .trending-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .trending-card {
      background: var(--white);
      border-radius: 12px;
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }

    .trending-card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,0.1); }

    .trending-img {
      height: 160px;
      background: var(--gray-100);
      position: relative;
      overflow: hidden;
    }

    .trending-img-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }

    .trending-card-body { padding: 16px; }

    .trending-category {
      display: inline-block;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--teal);
      margin-bottom: 6px;
    }

    .trending-card-title {
      font-size: 15px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* ===== NEWSLETTER ===== */
    .newsletter-section {
      background: linear-gradient(135deg, #02838D 0%, #016b75 100%);
      padding: 56px 0;
    }

    .newsletter-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }

    .newsletter-content {}

    .newsletter-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(255,255,255,0.15);
      color: rgba(255,255,255,0.9);
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      padding: 4px 12px;
      border-radius: 20px;
      margin-bottom: 16px;
    }

    .newsletter-title {
      font-size: clamp(24px, 3vw, 36px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.2;
      letter-spacing: -0.4px;
      margin-bottom: 14px;
    }

    .newsletter-body {
      font-size: 16px;
      color: rgba(255,255,255,0.8);
      line-height: 1.65;
    }

    .newsletter-form-wrap {}

    .newsletter-form {
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 16px;
      padding: 32px;
      backdrop-filter: blur(8px);
    }

    .newsletter-input-row {
      display: flex;
      gap: 10px;
      margin-bottom: 12px;
    }

    .newsletter-input {
      flex: 1;
      padding: 13px 18px;
      border-radius: 28px;
      border: none;
      font-size: 14.5px;
      font-family: inherit;
      outline: none;
      background: var(--white);
      color: var(--charcoal);
    }

    .newsletter-input::placeholder { color: var(--gray-400); }

    .newsletter-submit {
      padding: 13px 24px;
      background: #E8604C;
      color: var(--white);
      border-radius: 28px;
      font-size: 14.5px;
      font-weight: 700;
      transition: background 0.15s, transform 0.15s;
      white-space: nowrap;
    }

    .newsletter-submit:hover { background: #d44f3b; transform: translateY(-1px); }

    .newsletter-privacy {
      font-size: 12px;
      color: rgba(255,255,255,0.6);
      display: flex;
      align-items: center;
      gap: 6px;
    }

    /* ===== HEALTH TOPICS ===== */
    .topics-section {
      padding: 56px 0;
      background: var(--white);
    }

    .carousel-wrapper {
      position: relative;
    }

    .carousel-track-outer {
      overflow: hidden;
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .topic-card {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      cursor: pointer;
      flex-shrink: 0;
      width: 150px;
    }

    .topic-circle {
      width: 110px;
      height: 110px;
      border-radius: 50%;
      overflow: hidden;
      border: 3px solid var(--teal-mid);
      transition: border-color 0.2s, transform 0.2s;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 44px;
      background: var(--teal-light);
    }

    .topic-card:hover .topic-circle { border-color: var(--teal); transform: scale(1.05); }

    .topic-label {
      font-size: 13.5px;
      font-weight: 600;
      color: var(--charcoal);
      text-align: center;
      line-height: 1.3;
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--white);
      border: 1.5px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
      transition: all 0.15s;
      z-index: 2;
      color: var(--charcoal);
    }

    .carousel-btn:hover { border-color: var(--teal); color: var(--teal); }
    .carousel-btn.prev { left: -20px; }
    .carousel-btn.next { right: -20px; }

    /* ===== TOOLS ===== */
    .tools-section {
      padding: 56px 0;
      background: var(--gray-50);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    .tools-panel {
      background: var(--white);
      border-radius: 16px;
      border: 1px solid var(--gray-200);
      overflow: hidden;
    }

    .tools-panel-header {
      padding: 28px 28px 0;
    }

    .tools-panel-eyebrow {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--teal);
      margin-bottom: 8px;
    }

    .tools-panel-title {
      font-size: 20px;
      font-weight: 800;
      color: var(--charcoal);
      margin-bottom: 10px;
      letter-spacing: -0.3px;
    }

    .tools-panel-desc {
      font-size: 14px;
      color: var(--gray-600);
      line-height: 1.6;
      margin-bottom: 16px;
    }

    .tools-panel-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 14px;
      font-weight: 700;
      color: var(--white);
      background: var(--teal);
      padding: 9px 20px;
      border-radius: 22px;
      margin-bottom: 24px;
      transition: background 0.15s;
    }

    .tools-panel-cta:hover { background: var(--teal-dark); }

    .tools-list { border-top: 1px solid var(--gray-200); }

    .tool-item {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 14px 28px;
      border-bottom: 1px solid var(--gray-100);
      transition: background 0.12s;
      cursor: pointer;
    }

    .tool-item:last-child { border-bottom: none; }
    .tool-item:hover { background: var(--gray-50); }

    .tool-icon {
      width: 40px;
      height: 40px;
      border-radius: 10px;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;
    }

    .tool-info { flex: 1; }

    .tool-name {
      font-size: 14.5px;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 2px;
    }

    .tool-desc {
      font-size: 12.5px;
      color: var(--gray-500);
      line-height: 1.4;
    }

    .tool-arrow { color: var(--gray-400); }

    /* ===== RECOMMENDED READS ===== */
    .reads-section {
      padding: 56px 0;
      background: var(--white);
    }

    .reads-tabs {
      display: flex;
      gap: 4px;
      border-bottom: 2px solid var(--gray-200);
      margin-bottom: 32px;
      overflow-x: auto;
      scrollbar-width: none;
    }

    .reads-tabs::-webkit-scrollbar { display: none; }

    .reads-tab {
      padding: 10px 18px;
      font-size: 14px;
      font-weight: 600;
      color: var(--gray-500);
      white-space: nowrap;
      position: relative;
      transition: color 0.15s;
      border-radius: 6px 6px 0 0;
    }

    .reads-tab::after {
      content: '';
      position: absolute;
      bottom: -2px;
      left: 0;
      right: 0;
      height: 2px;
      background: var(--teal);
      transform: scaleX(0);
      transition: transform 0.2s;
    }

    .reads-tab.active { color: var(--teal); }
    .reads-tab.active::after { transform: scaleX(1); }
    .reads-tab:hover { color: var(--teal); }

    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .reads-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }

    .reads-card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,0.09); }

    .reads-card-img {
      height: 180px;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
    }

    .reads-card-body { padding: 18px; }

    .reads-card-category {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--teal);
      margin-bottom: 7px;
    }

    .reads-card-title {
      font-size: 16px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
      margin-bottom: 10px;
    }

    .reads-card-meta {
      font-size: 12px;
      color: var(--gray-400);
    }

    /* ===== TRUST ===== */
    .trust-section {
      padding: 72px 0;
      background: var(--charcoal);
    }

    .trust-header { text-align: center; margin-bottom: 48px; }

    .trust-title {
      font-size: clamp(24px, 3.5vw, 38px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.2;
      letter-spacing: -0.4px;
    }

    .trust-pillars {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 28px;
    }

    .trust-pillar {
      padding: 28px;
      background: rgba(255,255,255,0.05);
      border-radius: 16px;
      border: 1px solid rgba(255,255,255,0.08);
      transition: background 0.2s, border-color 0.2s;
    }

    .trust-pillar:hover {
      background: rgba(2, 131, 141, 0.15);
      border-color: rgba(2, 131, 141, 0.3);
    }

    .trust-pillar-icon {
      width: 52px;
      height: 52px;
      border-radius: 12px;
      background: var(--teal);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      margin-bottom: 16px;
    }

    .trust-pillar-name {
      font-size: 17px;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 10px;
      line-height: 1.3;
    }

    .trust-pillar-desc {
      font-size: 13.5px;
      color: rgba(255,255,255,0.65);
      line-height: 1.65;
    }

    /* ===== FEATURED PROGRAMS ===== */
    .programs-section {
      padding: 56px 0;
      background: var(--gray-50);
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .program-card {
      background: var(--white);
      border-radius: 12px;
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }

    .program-card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,0.09); }

    .program-img {
      height: 140px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
    }

    .program-img.c1 { background: linear-gradient(135deg, #f0fdf4, #dcfce7); }
    .program-img.c2 { background: linear-gradient(135deg, #eff6ff, #dbeafe); }
    .program-img.c3 { background: linear-gradient(135deg, #fef3c7, #fde68a); }
    .program-img.c4 { background: linear-gradient(135deg, #fdf2f8, #fce7f3); }

    .program-body { padding: 16px; }

    .program-tag {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--teal);
      margin-bottom: 6px;
    }

    .program-title {
      font-size: 15px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* ===== VIDEOS ===== */
    .videos-section {
      padding: 56px 0;
      background: var(--white);
    }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .video-card {
      border-radius: 12px;
      overflow: hidden;
      border: 1px solid var(--gray-200);
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .video-card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,0.1); }

    .video-thumb {
      height: 150px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 44px;
    }

    .video-thumb.v1 { background: linear-gradient(135deg, #e0f2fe, #b0e0ff); }
    .video-thumb.v2 { background: linear-gradient(135deg, #fce7f3, #fbcfe8); }
    .video-thumb.v3 { background: linear-gradient(135deg, #f0fdf4, #bbf7d0); }
    .video-thumb.v4 { background: linear-gradient(135deg, #fef9c3, #fef08a); }

    .video-play {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 48px;
      height: 48px;
      background: rgba(255,255,255,0.92);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 16px rgba(0,0,0,0.15);
      transition: transform 0.15s;
    }

    .video-card:hover .video-play { transform: translate(-50%, -50%) scale(1.1); }

    .video-body { padding: 14px; background: var(--white); }

    .video-category {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      color: var(--teal);
      margin-bottom: 5px;
    }

    .video-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* ===== FOOTER NEWSLETTER ===== */
    .footer-newsletter {
      background: var(--teal-light);
      padding: 48px 0;
      border-top: 1px solid var(--teal-mid);
    }

    .footer-nl-inner {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      align-items: center;
    }

    .footer-nl-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 8px;
    }

    .footer-nl-desc {
      font-size: 14px;
      color: var(--gray-600);
      line-height: 1.6;
    }

    .footer-nl-form {
      display: flex;
      gap: 10px;
      min-width: 360px;
    }

    .footer-nl-input {
      flex: 1;
      padding: 11px 18px;
      border-radius: 24px;
      border: 1.5px solid var(--teal-mid);
      font-size: 14px;
      font-family: inherit;
      outline: none;
      background: var(--white);
      color: var(--charcoal);
      transition: border-color 0.15s;
    }

    .footer-nl-input:focus { border-color: var(--teal); }

    .footer-nl-btn {
      padding: 11px 22px;
      background: var(--teal);
      color: var(--white);
      border-radius: 24px;
      font-size: 14px;
      font-weight: 700;
      transition: background 0.15s;
    }

    .footer-nl-btn:hover { background: var(--teal-dark); }

    /* ===== FOOTER ===== */
    .site-footer {
      background: var(--charcoal);
      color: rgba(255,255,255,0.7);
      padding: 40px 0 24px;
    }

    .footer-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
      padding-bottom: 28px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .footer-logo-text {
      font-size: 18px;
      font-weight: 800;
      color: var(--white);
    }

    .footer-social {
      display: flex;
      gap: 12px;
    }

    .social-link {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.15s;
      font-size: 16px;
    }

    .social-link:hover { background: var(--teal); }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 6px 0;
      margin-bottom: 28px;
    }

    .footer-link {
      font-size: 13px;
      color: rgba(255,255,255,0.55);
      padding: 4px 12px;
      transition: color 0.12s;
      border-right: 1px solid rgba(255,255,255,0.15);
    }

    .footer-link:last-child { border-right: none; }
    .footer-link:hover { color: var(--white); }

    .footer-legal {
      font-size: 12px;
      color: rgba(255,255,255,0.4);
      line-height: 1.6;
    }

    /* ===== TAB CONTENT PANELS ===== */
    .tab-panel { display: none; }
    .tab-panel.active { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .trending-grid { grid-template-columns: repeat(2, 1fr); }
      .trust-pillars { grid-template-columns: repeat(2, 1fr); }
      .programs-grid { grid-template-columns: repeat(2, 1fr); }
      .videos-grid { grid-template-columns: repeat(2, 1fr); }
      .hero-inner { grid-template-columns: 1fr; }
      .hero-visual { display: none; }
      .tools-grid { grid-template-columns: 1fr; }
      .newsletter-inner { grid-template-columns: 1fr; }
      .footer-nl-inner { grid-template-columns: 1fr; }
      .footer-nl-form { min-width: 0; }
    }

    @media (max-width: 640px) {
      .trending-grid { grid-template-columns: 1fr; }
      .trust-pillars { grid-template-columns: 1fr; }
      .programs-grid { grid-template-columns: 1fr; }
      .videos-grid { grid-template-columns: 1fr; }
      .reads-grid { grid-template-columns: 1fr; }
      .tab-panel.active { grid-template-columns: 1fr; }
      .header-actions .btn-outline { display: none; }
    }
  </style>
</head>
